# Lunar Konstruksi - Formwork TechnicalArc build hotfix
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Fail([string]$Message) { Write-Host "[FORMWORK FIX] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $parent = Split-Path -Parent $Path
  if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}
function Decode([string]$Value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail "Jalankan dari root repository Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot

$required = @(
  "components/site/formwork/decor.tsx",
  "components/site/formwork/about.tsx",
  "components/site/formwork/services.tsx",
  "components/site/formwork/projects.tsx",
  "components/site/formwork/contact.tsx"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) {
  $missing | ForEach-Object { Write-Host " - $_" }
  Fail "Komponen Formwork belum lengkap."
}

$backup = Join-Path $repoRoot (".lunar-backups/formwork-build-fix-" + (Get-Date -Format "yyyyMMdd-HHmmss"))
New-Item -ItemType Directory -Force -Path $backup | Out-Null
Copy-Item "components/site/formwork/decor.tsx" (Join-Path $backup "decor.tsx") -Force
Copy-Item "components/site/formwork/about.tsx" (Join-Path $backup "about.tsx") -Force

$decor = @'

'@
$about = @'

'@

Write-Utf8NoBom (Join-Path $repoRoot "components/site/formwork/decor.tsx") (Decode $decor)
Write-Utf8NoBom (Join-Path $repoRoot "components/site/formwork/about.tsx") (Decode $about)

Write-Host "[FORMWORK FIX] TechnicalArc compatibility diperbaiki." -ForegroundColor Green
Write-Host "[FORMWORK FIX] CTA About dibersihkan dari arc dekoratif besar." -ForegroundColor Green
Write-Host "[FORMWORK FIX] Backup: $backup" -ForegroundColor DarkGray
Write-Host ""
Write-Host "Jalankan:" -ForegroundColor Cyan
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
